// The Gmail trigger shape differs between "simple" and full mode, so read defensively.
const decode = (s) => Buffer.from(String(s).replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8');

const bodyFromPayload = (part) => {
  if (!part) return '';
  if (part.mimeType === 'text/plain' && part.body && part.body.data) return decode(part.body.data);
  for (const child of part.parts || []) {
    const found = bodyFromPayload(child);
    if (found) return found;
  }
  return '';
};

return $input.all().map((item) => {
  const m = item.json;
  const headers = {};
  for (const h of (m.payload && m.payload.headers) || []) headers[String(h.name).toLowerCase()] = h.value;

  const body = (m.text || bodyFromPayload(m.payload) || m.snippet || '').trim();
  const from = m.From || headers.from || '';
  const email = (from.match(/<([^>]+)>/) || [null, from])[1].trim().toLowerCase();

  return { json: {
    messageId: m.id || '',
    threadId: m.threadId || '',
    from,
    email,
    subject: m.Subject || headers.subject || '',
    body: body.slice(0, 4000)
  }};
});

